    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 m, address target) public {
        require(target != address(0));
        uint256 s0 = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 o0 = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 t0 = c.balanceOf(target); if (__ESBMC_reverted()) return;
        c.mintToken(address(this), m); if (__ESBMC_reverted()) return;
        c.burn(m); if (__ESBMC_reverted()) return;
        assert(c.totalSupply() == s0 + m - m && c.balanceOf(address(this)) == o0 + m - m && c.balanceOf(target) == t0);
