    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 m, address target) internal {
        vm.assume(target != address(0));
        uint256 s0;
        try c.totalSupply() returns (uint256 __r) { s0 = __r; } catch { return; }
        uint256 o0;
        try c.balanceOf(address(this)) returns (uint256 __r) { o0 = __r; } catch { return; }
        uint256 t0;
        try c.balanceOf(target) returns (uint256 __r) { t0 = __r; } catch { return; }
        try c.mintToken(address(this), m) {} catch { return; }
